True def transform(grid):
    """Mark every monochromatic full row or column with color 2."""
    h, w = len(grid), len(grid[0])
    marked = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            marked.update((r, c) for c in range(w))
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            marked.update((r, c) for r in range(h))
    out = [row[:] for row in grid]
    for r, c in marked:
        out[r][c] = 2
    return out
